partintro.section:
   &reftitle.intro;

कुनै undefined class वा unserialize को options array को allowed_classes मा सूचीकृत नभएको class लाई unserialize गर्न खोज्दा unserialize द्वारा सिर्जना गरिन्छ।


PHP 7.2.0 भन्दा पहिले, __PHP_Incomplete_Class class मा is_object प्रयोग गर्दा &false; return हुन्थ्यो। PHP 7.2.0 देखि, &true; return हुनेछ।

&reftitle.classsynopsis;
#[\AllowDynamicProperties] final __PHP_Incomplete_Class
यस class मा कुनै default properties वा methods हुँदैनन्। unserialize द्वारा सिर्जना गर्दा, सबै unserialize गरिएका properties र values का अतिरिक्त object मा एउटा __PHP_Incomplete_Class_Name property हुनेछ, जसमा unserialize गरिएको class को नाम रहनेछ।

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0
    यो class अब final भएको छ।

   &reftitle.examples;

    unserialize द्वारा सिर्जना गरिएको


<?php

class MyClass
{
    public string $property = "myValue";
}

$myObject = new MyClass;

$foo = serialize($myObject);

// unserializes all objects into __PHP_Incomplete_Class objects
$disallowed = unserialize($foo, ["allowed_classes" => false]);

var_dump($disallowed);

// unserializes all objects into __PHP_Incomplete_Class objects except those of MyClass2 and MyClass3
$disallowed2 = unserialize($foo, ["allowed_classes" => ["MyClass2", "MyClass3"]]);

var_dump($disallowed2);

// unserializes undefined class into __PHP_Incomplete_Class object
$undefinedClass = unserialize('O:16:"MyUndefinedClass":0:{}');

var_dump($undefinedClass);


    &example.outputs;



object(__PHP_Incomplete_Class)#2 (2) {
  ["__PHP_Incomplete_Class_Name"]=>
  string(7) "MyClass"
  ["property"]=>
  string(7) "myValue"
}
object(__PHP_Incomplete_Class)#3 (2) {
  ["__PHP_Incomplete_Class_Name"]=>
  string(7) "MyClass"
  ["property"]=>
  string(7) "myValue"
}
object(__PHP_Incomplete_Class)#4 (1) {
  ["__PHP_Incomplete_Class_Name"]=>
  string(16) "MyUndefinedClass"
}
